float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) { v += a * vnoise(p); p *= 2.02; a *= 0.5; }
    return v;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 2.5;
    float t = iTime * U.p0.x;
    vec2 q = vec2(fbm(uv + vec2(0.0, t)), fbm(uv + vec2(5.2, 1.3 - t)));
    vec2 r = vec2(fbm(uv + 4.0 * q + vec2(1.7, 9.2) + t), fbm(uv + 4.0 * q + vec2(8.3, 2.8) - t));
    float f = fbm(uv + 4.0 * r);
    float shade = clamp(f * f * 3.0, 0.0, 1.0);
    vec3 col = mix(vec3(0.02, 0.02, 0.09), vec3(0.05, 0.55, 0.85), shade);
    col = mix(col, vec3(0.85, 0.15, 0.55), clamp(length(q) * 0.9 - 0.15, 0.0, 1.0));
    col += vec3(1.0, 0.75, 0.35) * pow(clamp(r.x * 1.5, 0.0, 1.0), 4.0) * 1.2;
    col *= 0.35 + 1.1 * f;
    fragColor = vec4(col, 1.0);
}
